from scipy.optimize import least_squares
forms={
 "A(T)+B eps^n T^m exp(-k eps)": (lambda p,e,t: p[0]*t**p[1]+p[2]*e**p[3]*t**p[4]*np.exp(-p[5]*e), 6),
 "a T^b + c eps^d T^f + g eps T^h": (lambda p,e,t: p[0]*t**p[1]+p[2]*e**p[3]*t**p[4]+p[5]*e*t**p[6], 7),
 "(a+b eps^n) T^m": (lambda p,e,t: (p[0]+p[1]*e**p[2])*t**p[3], 4),
 "a T^b exp(c eps) + d eps^f": (lambda p,e,t: p[0]*t**p[1]*np.exp(p[2]*e)+p[3]*e**p[4], 5),
 "a T^b + c eps^d exp(f T)": (lambda p,e,t: p[0]*t**p[1]+p[2]*e**p[3]*np.exp(p[4]*t), 5),
 "a exp(bT)+c eps^d T^f": (lambda p,e,t: p[0]*np.exp(p[1]*t)+p[2]*e**p[3]*t**p[4], 5),
}
for name,(f,k) in forms.items():
    best=None
    for s in range(12):
        p0=np.random.rand(k)*1.5+0.2
        try:
            r=least_squares(lambda p: f(p,eps,T)-sigma, p0, max_nfev=3000)
            if np.isfinite(r.cost) and (best is None or r.cost<best.cost): best=r
        except Exception as ex: pass
    if best is not None:
        print(name, np.sum((f(best.x,eps,T)-sigma)**2)/np.sum((sigma-sigma.mean())**2), np.round(best.x,4))

