import numpy as np
def fitpoly(y, deg, transform):
    cols=[];names=[]
    for i in range(deg+1):
        for j in range(deg+1-i):
            cols.append(eps**i*T**j); names.append(f"e^{i}T^{j}")
    X=np.column_stack(cols)
    c=np.linalg.lstsq(X,y,rcond=None)[0]
    pred=X@c
    return np.sum((pred-y)**2)/np.sum((y-y.mean())**2)
for d in [3,4,5,6]:
